Write pytest tests for this function.

def parse_duration(text):
    units = {'h': 3600, 'm': 60, 's': 1}
    total, num = 0, ''
    for ch in text:
        if ch.isdigit():
            num += ch
        elif ch in units and num:
            total += int(num) * units[ch]
            num = ''
        else:
            raise ValueError(text)
    if num:
        raise ValueError(text)
    return total
